examples.code:
def obtener_elemento(lista, indice_str):
    try:
        idx = int(indice_str)
        return lista[idx]
    except ValueError:
        return "El índice debe ser un número entero"
    except IndexError:
        return "Índice fuera del rango de la lista"

print(obtener_elemento([10, 20], "0"))
print(obtener_elemento([10, 20], "5"))
print(obtener_elemento([10, 20], "abc"))

