examples.code:
def prueba(divisor):
    try:
        res = 20 / divisor
    except ZeroDivisionError:
        print("Excepcion atrapada")
    else:
        print("Exito:", res)
    finally:
        print("Bloque finally ejecutado")

print("--- Caso 1 ---")
prueba(4)
print("--- Caso 2 ---")
prueba(0)

