examples.code:
class AutenticacionError(Exception):
    pass

def iniciar_sesion(clave):
    if clave != "secreto123":
        raise AutenticacionError("Clave incorrecta")
    return "Acceso concedido"

try:
    iniciar_sesion("incorrecta")
except AutenticacionError as e:
    print("Fallo de seguridad:", e)

